-- ================= SECCIÓN 1. Composición y Procedimiento Electoral
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, color_clase, titulo, contenido_html, orden)
VALUES (3, NULL, 'seccion', '1', 'c1', 'Composición y Procedimiento Electoral', '<p>A continuación se presenta un resumen completo y estructurado de la composición de las Cortes Generales y su procedimiento electoral, con base en la Constitución Española de 1978, la Ley Orgánica del Régimen Electoral General (LOREG) y los Reglamentos del Congreso y del Senado.</p>', 1);
SET @seccion_id := LAST_INSERT_ID();

INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (3, @seccion_id, 'epigrafe', '1.1', 'Las Cortes Generales: concepto, denominación y funciones', '<ul class="uji-lista"><li>Las Cortes Generales son el órgano constitucional supremo del Estado español, regulado en el Título III de la Constitución (arts. 66 a 96).</li></ul><div class="uji-cita"><p><strong>Artículo 66.1 CE</strong> Las Cortes Generales representan al pueblo español y están formadas por el Congreso de los Diputados y el Senado.</p></div><p>Aunque la Constitución evita el término "Parlamento", utiliza expresiones como "Monarquía parlamentaria" (art. 1.3 CE), "representación parlamentaria" (art. 99.1 CE) o "confianza parlamentaria" (art. 101.1 CE), por lo que es admisible referirse a las Cortes como Parlamento en sentido material.</p><p><strong>Funciones de las Cortes Generales (art. 66.2 CE)</strong></p><ul class="uji-lista"><li>Ejercer la potestad legislativa del Estado (elaborar y aprobar las leyes).</li><li>Aprobar los Presupuestos Generales del Estado (PGE).</li><li>Controlar la acción del Gobierno (a través de preguntas, interpelaciones, mociones, moción de censura, cuestión de confianza, etc.).</li><li>Las demás competencias que les atribuya la Constitución (por ejemplo, autorizar tratados internacionales, nombrar miembros del Tribunal Constitucional y del CGPJ, etc.).</li><li>Funciones derivadas de su propia autonomía normativa (aprobar sus Reglamentos).</li></ul>', 1);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (3, @seccion_id, 'epigrafe', '1.2', 'Composición del Congreso de los Diputados', '<div class="uji-cita"><p><strong>Artículo 68.1 CE</strong> El Congreso se compone de un mínimo de 300 y un máximo de 400 Diputados, elegidos por sufragio universal, libre, igual, directo y secreto, en los términos que establezca la ley.</p></div><p>Actualmente, la Ley Orgánica 5/1985, de 19 de junio, del Régimen Electoral General (LOREG) fija en 350 diputados el número total.</p><p><strong>Criterios de distribución (art. 68.2 CE)</strong></p><ul class="uji-lista"><li>La circunscripción electoral es la provincia.</li><li>Ceuta y Melilla eligen cada una 1 Diputado.</li><li>La ley asigna una representación mínima inicial a cada circunscripción y distribuye los restantes en proporción a la población.</li></ul><p><strong>Aplicación práctica según LOREG</strong></p><ul class="uji-lista"><li>Cada provincia recibe un mínimo de 2 diputados.</li><li>Ceuta y Melilla: 1 diputado cada una.</li><li>Total de diputados por mínimo inicial: 50 provincias × 2 = 100, + 2 = 102 diputados.</li><li>Los restantes 248 diputados se distribuyen proporcionalmente según la población de cada provincia.</li></ul><p>Ejemplo (elecciones generales de 2019): Soria tenía 2 diputados; Madrid tenía 37 diputados.</p><p>Sistema electoral (art. 68.3 CE): la elección se verifica en cada circunscripción atendiendo a criterios de representación proporcional (sistema D\'Hondt).</p><p>Duración del mandato (art. 68.4 CE): el Congreso es elegido por cuatro años. El mandato de los Diputados termina cuatro años después de su elección o el día de la disolución de la Cámara. Puede haber disolución anticipada por voluntad del Presidente del Gobierno previa deliberación del Consejo de Ministros (art. 115 CE).</p><p>Derecho de sufragio (art. 68.5 CE): son electores y elegibles todos los españoles que estén en pleno uso de sus derechos políticos. El Estado facilitará el ejercicio del derecho de sufragio a los españoles residentes en el extranjero (voto rogado).</p><p>Plazos postelectorales (art. 68.6 CE): las elecciones se celebran entre los 30 y 60 días siguientes a la terminación del mandato. El Congreso electo debe ser convocado dentro de los 25 días siguientes a la celebración de las elecciones.</p><p>Aportación del Reglamento del Congreso (arts. 1-5): el Reglamento regula la sesión constitutiva, que se celebra el día y hora señalados en el Real Decreto de convocatoria (art. 1). La preside inicialmente el Diputado de mayor edad, asistido por los dos más jóvenes como Secretarios (art. 2). Tras la lectura del Real Decreto y la relación de electos, se procede a la elección de la Mesa (art. 3). Finalizadas las votaciones, el Presidente presta y solicita juramento o promesa de acatar la Constitución (art. 4.1). Finalmente, dentro de los quince días siguientes tiene lugar la solemne sesión de apertura de la legislatura (art. 5).</p>', 2);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (3, @seccion_id, 'epigrafe', '1.3', 'Composición del Senado', '<div class="uji-cita"><p><strong>Artículo 69.1 CE</strong> El Senado es la Cámara de representación territorial.</p></div><p>A diferencia del Congreso (representación proporcional), el Senado se basa en una representación territorial, combinando elección directa en circunscripciones provinciales y designación por las Comunidades Autónomas.</p><p><strong>A) Senadores elegidos por sufragio (arts. 69.2, 69.3 y 69.4 CE)</strong></p><ul class="uji-lista"><li>Provincias peninsulares: 4 senadores por cada provincia.</li><li>Islas mayores (Gran Canaria, Mallorca y Tenerife): 3 senadores cada una.</li><li>Islas menores (Ibiza-Formentera, Menorca, Fuerteventura, Gomera, Hierro, Lanzarote y La Palma): 1 senador cada una.</li><li>Ceuta y Melilla: 2 senadores cada una.</li></ul><p><strong>B) Senadores designados por las Comunidades Autónomas (art. 69.5 CE)</strong></p><ul class="uji-lista"><li>Cada Comunidad Autónoma designa 1 Senador más otro por cada millón de habitantes de su territorio.</li><li>La designación corresponde a la Asamblea legislativa (Parlamento autonómico) o, en su defecto, al órgano colegiado superior de la CCAA.</li><li>Los Estatutos de Autonomía deben asegurar la adecuada representación proporcional en la designación.</li><li>Se configura como una elección indirecta o de segundo grado: los senadores no son elegidos directamente por la población, sino por los representantes elegidos por esta.</li></ul><p>Número total: actualmente, el Senado está compuesto por 266 senadores en la XV Legislatura (208 elegidos por sufragio + 58 designados por las CCAA, aunque el número varía según la población).</p><p>Duración del mandato (art. 69.6 CE): el Senado es elegido por cuatro años. El mandato de los Senadores termina cuatro años después de su elección o el día de la disolución de la Cámara. Puede ser disuelto anticipadamente al igual que el Congreso.</p>', 3);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (3, @seccion_id, 'epigrafe', '1.4', 'Procedimiento electoral general', '<p>Marco normativo: la Ley Orgánica 5/1985, de 19 de junio, del Régimen Electoral General (LOREG) es la norma que desarrolla el régimen electoral y su procedimiento.</p><p><strong>A) Derecho de sufragio (art. 23 CE)</strong></p><p><strong>Artículo 23.1 CE – Sufragio activo (derecho a votar)</strong></p><ul class="uji-lista"><li>Corresponde a los españoles mayores de edad.</li><li>Con algunas excepciones: condenados por sentencia judicial firme, incapacitados judicialmente por trastornos psiquiátricos, etc.</li><li>Es indispensable estar inscrito en el censo electoral.</li><li>El sufragio se ejerce personalmente, no pudiendo votar más de una vez en cada elección.</li><li>Es un derecho libre (no se puede obligar ni coaccionar) y secreto (no se puede revelar el voto).</li></ul><p><strong>Artículo 23.2 CE – Sufragio pasivo (derecho a ser elegido)</strong></p><ul class="uji-lista"><li>Son elegibles todos los españoles mayores de edad que posean la cualidad de elector.</li><li>La LOREG explicita las diferentes causas de ineligibilidad (por ejemplo, condenados a penas graves, determinados altos cargos públicos, etc.).</li></ul><p><strong>B) Sujetos legitimados para presentar candidaturas (arts. 44 y ss. LOREG)</strong></p><p>Pueden presentar candidatos o listas de candidatos:</p><ul class="uji-lista"><li>Los partidos y federaciones inscritos en el registro correspondiente.</li><li>Las coaliciones constituidas conforme a la LOREG (deben comunicarlo a la Junta Electoral competente en los diez días siguientes a la convocatoria).</li><li>Las agrupaciones de electores que reúnan los requisitos establecidos.</li></ul><p><strong>Reglas importantes</strong></p><ul class="uji-lista"><li>Ningún partido, federación, coalición o agrupación puede presentar más de una lista de candidatos en una misma circunscripción.</li><li>Los partidos federados o coaligados no pueden presentar candidaturas propias en una circunscripción si concurre la coalición a la que pertenecen.</li></ul><p>Composición equilibrada (art. 44 bis LOREG): las candidaturas deben tener una composición equilibrada de mujeres y hombres, de forma que en el conjunto de la lista los candidatos de cada uno de los sexos supongan como mínimo el cuarenta por ciento.</p><p>Plazo de presentación: las candidaturas se presentan ante la Junta Electoral competente entre el 15º y 20º día posteriores a la convocatoria. El escrito de presentación debe expresar claramente la denominación, siglas y símbolo del partido, federación, coalición o agrupación que la promueve, así como el nombre y apellidos de los candidatos.</p><p>Publicación: las candidaturas presentadas deben ser publicadas el 22º día posterior a la convocatoria.</p>', 4);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (3, @seccion_id, 'epigrafe', '1.5', 'Procedimiento electoral para el Congreso de los Diputados', '<p>Sistema electoral: representación proporcional (art. 68.3 CE). Se aplica la ley D\'Hondt para la atribución de escaños.</p><p>Forma de las listas: listas cerradas y bloqueadas. El elector vota a una lista completa, sin posibilidad de alterar el orden ni seleccionar candidatos individuales.</p><p>Circunscripción: la provincia (art. 68.2 CE). Cada circunscripción tiene un mínimo de 2 diputados, salvo Ceuta y Melilla que tienen 1.</p><p>Votación: el elector introduce una papeleta con la lista completa de candidatos de una formación política en un sobre, que deposita en la urna.</p><p><strong>Representantes de candidaturas (art. 168 LOREG)</strong></p><ul class="uji-lista"><li>Los partidos, federaciones y coaliciones designan un representante general ante la Junta Electoral Central (antes del 9º día tras la convocatoria).</li><li>Cada representante general designa a los representantes de las candidaturas en cada circunscripción (antes del 11º día tras la convocatoria).</li><li>Las Juntas Electorales competentes para todas las operaciones de presentación y proclamación de candidatos son las Juntas Electorales Provinciales (art. 169 LOREG).</li></ul>', 5);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (3, @seccion_id, 'epigrafe', '1.6', 'Procedimiento electoral para el Senado', '<p>Sistema electoral: escrutinio mayoritario plurinominal con voto limitado. Aunque los candidatos aparecen agrupados en listas por partidos, las candidaturas son individuales a efectos de votación y escrutinio. El elector puede votar a candidatos de diferentes fuerzas políticas.</p><p>Forma de las listas: listas abiertas (no bloqueadas). El elector marca con una cruz los candidatos de su preferencia.</p><p><strong>Número de votos por elector</strong></p><ul class="uji-lista"><li>Circunscripciones provinciales (4 senadores): el elector puede votar hasta 3 candidatos.</li><li>Islas mayores (3 senadores): el elector puede votar hasta 2 candidatos.</li><li>Ceuta, Melilla e islas menores (2 o 1 senador): el elector puede votar hasta 2 candidatos (en las de 1 senador, solo puede votar a 1).</li></ul><p>Candidatos suplentes: cada candidatura a Senador debe incluir un candidato suplente (art. 171.2 LOREG).</p><p><strong>Papeleta electoral (art. 172 LOREG)</strong></p><ul class="uji-lista"><li>La papeleta incluye la denominación o sigla del partido, federación, coalición o agrupación.</li><li>Bajo esta denominación, figuran los nombres de los candidatos por orden alfabético, cada uno con un recuadro precedente.</li><li>Debajo del nombre de cada candidato aparece el de su suplente.</li><li>El votante marca con una cruz el recuadro del candidato o candidatos a los que otorga su voto.</li></ul><p>Requisitos para agrupaciones de electores (art. 169.3 LOREG): para presentar candidaturas al Senado, las agrupaciones de electores necesitan al menos la firma del 1% de los inscritos en el censo electoral de la circunscripción.</p><p>Representantes de candidaturas (arts. 168-169 LOREG): al igual que en el Congreso, las Juntas Electorales Provinciales son competentes para la presentación y proclamación de candidatos. Los promotores de las agrupaciones de electores designan a los representantes de sus candidaturas en el momento de la presentación.</p>', 6);

-- ================= SECCIÓN 2. Autonomía de las Cámaras
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, color_clase, titulo, orden)
VALUES (3, NULL, 'seccion', '2', 'c2', 'Autonomía de las Cámaras', 2);
SET @seccion_id := LAST_INSERT_ID();

INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (3, @seccion_id, 'epigrafe', '2.1', 'Concepto y fundamento constitucional de la autonomía', '<p>La autonomía de las Cortes Generales es un principio constitucional que garantiza la independencia del Parlamento frente a los demás poderes del Estado (Gobierno, Poder Judicial, Monarquía). Se trata de un conjunto de medidas y garantías que permiten a las Cámaras organizarse y funcionar sin injerencias externas.</p><p><strong>Fundamento constitucional principal</strong></p><div class="uji-cita"><p><strong>Artículo 66.3 CE</strong> Las Cortes Generales son inviolables.</p></div><p>Esta declaración de inviolabilidad protege a las Cortes en su conjunto como institución, impidiendo que puedan ser cuestionadas, disueltas ilegalmente o coaccionadas por otros poderes.</p><p>Además, el artículo 67 CE refuerza esta idea con tres disposiciones clave:</p><ul class="uji-lista"><li><strong>67.1 CE</strong> — Nadie puede ser miembro de las dos Cámaras simultáneamente, ni acumular el acta de Diputado con la de miembro de una Asamblea de Comunidad Autónoma. Evita conflictos de intereses y concentración de poder.</li><li><strong>67.2 CE</strong> — Los miembros de las Cortes Generales no estarán ligados por mandato imperativo. No reciben instrucciones de nadie; votan según su conciencia.</li><li><strong>67.3 CE</strong> — Las reuniones de Parlamentarios sin convocatoria reglamentaria no vinculan a las Cámaras, y no podrán ejercer sus funciones ni ostentar sus privilegios. Solo los actos realizados conforme al Reglamento tienen validez oficial.</li></ul>', 1);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (3, @seccion_id, 'epigrafe', '2.2', 'Garantías constitucionales de la autonomía', '<p>El artículo 71 CE establece las principales garantías individuales de los parlamentarios, que son esenciales para la autonomía colectiva de las Cámaras:</p><ul class="uji-lista"><li><strong>Inviolabilidad — Art. 71.1 CE</strong> — los Diputados y Senadores gozan de inviolabilidad por las opiniones manifestadas en el ejercicio de sus funciones, incluso después de haber cesado en su mandato. No pueden ser perseguidos penal ni civilmente por sus votos o discursos parlamentarios.</li><li><strong>Inmunidad — Art. 71.2 CE</strong> — durante su mandato, solo pueden ser detenidos en caso de flagrante delito. No pueden ser inculpados ni procesados sin la previa autorización de la Cámara respectiva (suplicatorio).</li><li><strong>Fuero especial — Art. 71.3 CE</strong> — en las causas contra Diputados y Senadores, es competente la Sala de lo Penal del Tribunal Supremo.</li><li><strong>Asignación económica — Art. 71.4 CE</strong> — los Diputados y Senadores percibirán una asignación fijada por las respectivas Cámaras, lo que asegura su independencia económica frente al Gobierno.</li></ul><p>Estas garantías no son privilegios personales, sino garantías funcionales que protegen la independencia del Parlamento frente a posibles represalias o presiones de otros poderes.</p>', 2);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (3, @seccion_id, 'epigrafe', '2.3', 'Manifestaciones de la autonomía de las Cámaras', '<p>La autonomía de las Cortes Generales se concreta en cuatro grandes poderes o manifestaciones:</p><p><strong>A) Poderes de autorregulación</strong></p><ul class="uji-lista"><li>Cada Cámara tiene la facultad de elaborar autónomamente sus propios Reglamentos (art. 72.1 CE).</li><li>El Reglamento es la norma interna que regula la organización y el funcionamiento de la Cámara.</li><li>Reglamento de las Cortes Generales: el artículo 72.2 CE prevé un Reglamento de las Cortes Generales para las sesiones conjuntas, pero nunca ha sido aprobado (requiere mayoría absoluta de cada Cámara). En su defecto, se aplican supletoriamente los Reglamentos de cada Cámara.</li><li>Reglamento del Congreso de los Diputados: aprobado el 10 de febrero de 1982 (texto consolidado de septiembre de 2025).</li><li>Reglamento del Senado: aprobado el 3 de mayo de 1994 (texto refundido con última modificación en noviembre de 2025).</li></ul><p>Procedimiento de aprobación y reforma (art. 72.1 CE): los Reglamentos y su reforma se someten a una votación final sobre su totalidad que requiere mayoría absoluta de la Cámara.</p><p><strong>B) Poderes de autogobierno</strong></p><ul class="uji-lista"><li>La Mesa: es el órgano rector de cada Cámara (art. 30 Reglamento Congreso; art. 35 Reglamento Senado). Ostenta la representación colegiada de la Cámara.</li><li>Congreso: Presidente, 4 Vicepresidentes y 4 Secretarios.</li><li>Senado: Presidente, 2 Vicepresidentes y 4 Secretarios.</li><li>El Presidente: es el director y coordinador de la acción de la Mesa. Ostenta la representación de la Cámara, dirige los debates, mantiene el orden y ejerce los poderes de policía en el interior de la sede parlamentaria (art. 32 Reglamento Congreso; arts. 37-38 Reglamento Senado).</li><li>Elección de la Mesa: se realiza en la sesión constitutiva de cada legislatura mediante votación de los propios parlamentarios, sin intervención de ningún otro poder.</li></ul><p><strong>C) Autonomía financiera</strong></p><div class="uji-cita"><p><strong>Art. 72.1 CE</strong> Las Cámaras establecen sus propios Reglamentos, aprueban autónomamente sus presupuestos y, de común acuerdo, regulan el Estatuto del Personal de las Cortes Generales.</p></div><ul class="uji-lista"><li>Cada Cámara elabora y aprueba su propio proyecto de presupuesto (art. 31 Reglamento Congreso; art. 36 Reglamento Senado).</li><li>Los presupuestos de las Cámaras se incorporan a los Presupuestos Generales del Estado (PGE), pero las Cámaras deciden autónomamente su cuantía y distribución.</li><li>Ejecución presupuestaria: la Mesa ordena los gastos y controla la ejecución (art. 31.2.3º Reglamento Congreso).</li><li>Remanentes: en el Senado, los remanentes presupuestarios constituyen recursos financieros propios de la Cámara (Disposición Adicional Sexta Reglamento Senado).</li></ul><p><strong>D) Garantías de autonomía (individuales y colectivas)</strong></p><ul class="uji-lista"><li><strong>Incompatibilidades</strong> — Art. 67.1 CE (no ser miembro de ambas Cámaras ni de Asamblea autonómica) — Arts. 15-19 Reglamento Congreso; arts. 15-17 Reglamento Senado.</li><li><strong>Inviolabilidad</strong> — Art. 71.1 CE — Art. 10 Reglamento Congreso; art. 21 Reglamento Senado.</li><li><strong>Inmunidad y suplicatorio</strong> — Art. 71.2 CE — Arts. 11-14 Reglamento Congreso; art. 22 Reglamento Senado.</li><li><strong>Fuero del TS</strong> — Art. 71.3 CE — (Desarrollo procesal en LOPJ).</li><li><strong>Asignación económica</strong> — Art. 71.4 CE — Art. 8 Reglamento Congreso; arts. 23-24 Reglamento Senado.</li></ul>', 3);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (3, @seccion_id, 'epigrafe', '2.4', 'Desarrollo reglamentario de la autonomía', '<p>Los Reglamentos desarrollan y concretan estas garantías:</p><p><strong>A) Reglamento del Congreso de los Diputados</strong></p><ul class="uji-lista"><li><strong>Inviolabilidad — Art. 10</strong> — inviolabilidad por opiniones manifestadas en el ejercicio de funciones, aun después del cese.</li><li><strong>Inmunidad — Art. 11</strong> — detención solo en flagrante delito; necesidad de suplicatorio para procesar.</li><li><strong>Suplicatorio — Arts. 13-14</strong> — procedimiento de autorización: Comisión del Estatuto (30 días), Pleno, silencio denegatorio a los 60 días.</li><li><strong>Deberes — Arts. 15-19</strong> — asistencia, respeto al Reglamento, no usar la condición para actividades mercantiles, declaración de bienes.</li><li><strong>Asignación — Art. 8</strong> — fijada por la Mesa; derechos a ayudas e indemnizaciones; cotizaciones a Seguridad Social.</li><li><strong>Incompatibilidades — Art. 19</strong> — observar normas de incompatibilidades; opción entre escaño y cargo en 8 días.</li></ul><p><strong>B) Reglamento del Senado</strong></p><ul class="uji-lista"><li><strong>Inviolabilidad — Art. 21</strong> — inviolabilidad por opiniones manifestadas en actos parlamentarios y votos emitidos.</li><li><strong>Inmunidad — Art. 22</strong> — detención solo en flagrante delito; suplicatorio; suspensión temporal por mayoría absoluta.</li><li><strong>Declaraciones obligatorias — Art. 26</strong> — declaración de actividades, bienes patrimoniales y rentas, e intereses económicos.</li><li><strong>Asignación — Art. 23</strong> — asignación, dietas e indemnizaciones; publicación en web; privación por inasistencia reiterada.</li><li><strong>Derecho a información — Art. 25</strong> — acceso a actas y documentos con límites.</li><li><strong>Previsión social — Art. 24</strong> — Seguridad Social, clases pasivas, sistema de previsión con pensiones de retiro.</li></ul><p><strong>C) Resumen de las garantías de autonomía</strong></p><ul class="uji-lista"><li><strong>Autorregulación</strong> — Art. 72.1 CE — Reglamento del Congreso (1982); Reglamento del Senado (1994) — órgano competente: Pleno (mayoría absoluta).</li><li><strong>Autogobierno</strong> — Art. 72.2 CE (elección de Mesas) — Arts. 30-38 (Congreso); arts. 35-42 (Senado) — órgano competente: Pleno.</li><li><strong>Autonomía financiera</strong> — Art. 72.1 CE — Arts. 31 (Congreso); art. 36 (Senado) — órgano competente: Mesa (elaboración); Pleno (aprobación).</li><li><strong>Inviolabilidad</strong> — Art. 71.1 CE — Art. 10 (Congreso); art. 21 (Senado) — directa.</li><li><strong>Inmunidad</strong> — Art. 71.2 CE — Arts. 11-14 (Congreso); art. 22 (Senado) — órgano competente: Pleno (concesión/denegación).</li><li><strong>Fuero especial</strong> — Art. 71.3 CE — LOPJ (desarrollo procesal) — órgano competente: Sala Penal del TS.</li><li><strong>Asignación económica</strong> — Art. 71.4 CE — Art. 8 (Congreso); art. 23 (Senado) — órgano competente: Mesa.</li><li><strong>Poder de policía</strong> — Art. 72.3 CE — Arts. 105-107 (Congreso); arts. 38-39 (Senado) — órgano competente: Presidente.</li><li><strong>Incompatibilidades</strong> — Art. 67.1 CE — Art. 19 (Congreso); arts. 15-17 (Senado) — órgano competente: Comisión de Incompatibilidades / Pleno.</li></ul>', 4);

-- ================= SECCIÓN 3. Derechos y Deberes de los Diputados y Senadores
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, color_clase, titulo, orden)
VALUES (3, NULL, 'seccion', '3', 'c3', 'Derechos y Deberes de los Diputados y Senadores', 3);
SET @seccion_id := LAST_INSERT_ID();

INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (3, @seccion_id, 'epigrafe', '3.1', 'Derechos de los Diputados y Senadores', '<p><strong>A) Garantías constitucionales (derechos fundamentales)</strong></p><p>Estas garantías, ya comentadas en el epígrafe de autonomía, son también derechos individuales de los parlamentarios: mandato imperativo (prohibición del), inmunidad, inviolabilidad, aforamiento, asignación.</p><p><strong>B) Derechos constitucionales de información y control</strong></p><ul class="uji-lista"><li><strong>Reclamar la presencia del Gobierno — Art. 110.1 CE</strong> — las Cámaras y sus Comisiones pueden reclamar la presencia de los miembros del Gobierno.</li><li><strong>Acceso del Gobierno a las Cámaras — Art. 110.2 CE</strong> — los miembros del Gobierno tienen acceso a las sesiones y la facultad de hacerse oír.</li><li><strong>Recabar información — Art. 109 CE</strong> — las Cámaras y sus Comisiones pueden recabar, a través de sus Presidentes, la información y ayuda que precisen del Gobierno, sus Departamentos y cualquier autoridad del Estado y CCAA.</li></ul><p><strong>C) Derechos reconocidos en el Reglamento del Congreso</strong></p><ul class="uji-lista"><li><strong>Asistencia y voto — Art. 6.1</strong> — derecho a asistir con voto a las sesiones del Pleno y de las Comisiones de que formen parte. Pueden asistir sin voto a las Comisiones de las que no formen parte.</li><li><strong>Formar parte de una Comisión — Art. 6.2</strong> — derecho a formar parte, al menos, de una Comisión.</li><li><strong>Uso de lenguas oficiales — Art. 6.3</strong> — derecho a usar cualquiera de las lenguas oficiales en los ámbitos de la actividad parlamentaria.</li><li><strong>Recabar información de las Administraciones — Art. 7</strong> — facultad de recabar datos, informes o documentos de las Administraciones públicas, previo conocimiento del Grupo Parlamentario. La solicitud se dirige por conducto de la Presidencia.</li><li><strong>Asignación económica — Art. 8.1</strong> — perciben una asignación económica para cumplir eficaz y dignamente su función.</li><li><strong>Ayudas e indemnizaciones — Art. 8.2</strong> — derecho a ayudas, franquicias e indemnizaciones por gastos indispensables.</li><li><strong>Cotizaciones a la Seguridad Social — Art. 9</strong> — a cargo del Presupuesto del Congreso cuando, por dedicación parlamentaria, dejen de prestar el servicio que motivaba su afiliación.</li></ul><p><strong>D) Derechos reconocidos en el Reglamento del Senado</strong></p><ul class="uji-lista"><li><strong>Asistencia y voto — Art. 20.1</strong> — derecho y deber de asistir a las sesiones plenarias y a las de las Comisiones de que formen parte, y a votar.</li><li><strong>Uso de lenguas oficiales — Art. 20.3</strong> — los Senadores pueden utilizar cualquiera de las lenguas oficiales para la presentación de escritos en el Registro de la Cámara.</li><li><strong>Recabar información — Art. 20 bis</strong> — facultad de recabar datos, informes o documentos de la Administración General del Estado y organismos públicos. Plazo de 30 días para respuesta. Si se deniega, pueden solicitar a la Mesa que se pronuncie.</li><li><strong>Asignación, dietas e indemnizaciones — Art. 23.1</strong> — derecho a asignación, dietas e indemnizaciones por gastos necesarios para el desempeño de su función.</li><li><strong>Publicación de percepciones — Art. 23.2</strong> — las percepciones se publican en la página web del Senado.</li><li><strong>Pase de libre circulación — Art. 24.1</strong> — derecho a pase de libre circulación en medios de transporte colectivo o pago de gastos de viaje.</li><li><strong>Seguridad Social y previsión — Art. 24.2-24.3</strong> — cotizaciones a cargo del Senado; sistema de previsión con pensiones de retiro.</li><li><strong>Acceso a actas y documentos — Art. 25</strong> — derecho a solicitar el conocimiento de actas y documentos, con los límites previstos en el ordenamiento jurídico.</li></ul>', 1);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (3, @seccion_id, 'epigrafe', '3.2', 'Deberes de los Diputados y Senadores', '<p><strong>A) Deberes en el Reglamento del Congreso</strong></p><ul class="uji-lista"><li><strong>Asistencia — Art. 15</strong> — deber de asistir a las sesiones del Pleno y de las Comisiones de que formen parte.</li><li><strong>Conducta adecuada — Art. 16</strong> — obligación de adecuar su conducta al Reglamento, respetar el orden, la cortesía y la disciplina parlamentarias.</li><li><strong>Secreto — Art. 16</strong> — no divulgar las actuaciones que tengan carácter secreto.</li><li><strong>No usar la condición para actividades mercantiles — Art. 17</strong> — no podrán invocar o hacer uso de su condición de parlamentarios para el ejercicio de actividad mercantil, industrial o profesional.</li><li><strong>Declaración de bienes — Art. 18</strong> — obligación de formular declaración de sus bienes patrimoniales en los términos previstos en la LOREG.</li><li><strong>Incompatibilidades — Art. 19.1</strong> — deber de observar en todo momento las normas sobre incompatibilidades establecidas en la Constitución y en la Ley Electoral.</li><li><strong>Opción entre escaño y cargo incompatible — Art. 19.3</strong> — declarada la incompatibilidad, disponen de 8 días para optar. Si no ejercitan la opción, se entiende que renuncian al escaño.</li></ul><p><strong>B) Deberes en el Reglamento del Senado</strong></p><ul class="uji-lista"><li><strong>Asistencia — Art. 20.1</strong> — derecho y deber de asistir a las sesiones plenarias y a las de las Comisiones.</li><li><strong>Declaraciones obligatorias — Art. 26</strong> — declaración de actividades, bienes patrimoniales y rentas, e intereses económicos.</li><li><strong>Comunicación de alteraciones — Art. 16.5</strong> — obligación de comunicar a la Comisión de Incompatibilidades cualquier alteración de las circunstancias declaradas en el plazo de 30 días.</li><li><strong>Respuesta a requerimientos — Art. 16.2</strong> — deber de responder a los requerimientos de documentación complementaria en el plazo de un mes.</li></ul>', 2);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (3, @seccion_id, 'epigrafe', '3.3', 'El Suplicatorio: procedimiento de autorización judicial', '<p>El suplicatorio es el procedimiento mediante el cual un tribunal solicita a la Cámara correspondiente la autorización para procesar a un diputado o senador, conforme al artículo 71.2 CE.</p><p><strong>A) Regulación en el Reglamento del Congreso (arts. 12-14)</strong></p><ul class="uji-lista"><li><strong>1. Medidas cautelares — Art. 12 (inmediato)</strong> — el Presidente, conocida la detención de un diputado o cualquier actuación judicial que pueda obstaculizar el mandato, adopta medidas para salvaguardar los derechos de la Cámara y sus miembros.</li><li><strong>2. Recepción y calificación — Art. 13.1 (5 días)</strong> — recibido el suplicatorio, el Presidente, previo acuerdo de la Mesa, lo remite a la Comisión del Estatuto de los Diputados. No se admiten los que no cumplan los requisitos procesales.</li><li><strong>3. Audiencia y dictamen — Art. 13.2 (30 días)</strong> — la Comisión del Estatuto, con audiencia del interesado, concluye su trabajo. La audiencia puede ser escrita u oral.</li><li><strong>4. Debate en el Pleno — Art. 13.3 (primer Pleno)</strong> — la cuestión, documentada, se somete al primer Pleno ordinario de la Cámara.</li><li><strong>5. Traslado al tribunal — Art. 14.1 (8 días)</strong> — en 8 días desde el acuerdo del Pleno, el Presidente da traslado al tribunal, advirtiendo de la obligación de comunicar autos y sentencias.</li><li><strong>6. Silencio denegatorio — Art. 14.2 (60 días)</strong> — el suplicatorio se entiende denegado si la Cámara no se pronuncia en 60 días naturales desde su recepción (durante período de sesiones).</li></ul><p><strong>B) Regulación en el Reglamento del Senado (art. 22)</strong></p><ul class="uji-lista"><li><strong>Detención (24 horas)</strong> — la detención se comunica a la Presidencia en 24 horas.</li><li><strong>Calificación (inmediato)</strong> — el Presidente somete el suplicatorio a la calificación de la Mesa.</li><li><strong>Dictamen (30 días)</strong> — se remite a la Comisión de Suplicatorios, que con audiencia del interesado emite dictamen (sesiones secretas).</li><li><strong>Debate en Pleno (primera sesión)</strong> — el Pleno, en sesión secreta, debate el dictamen (turno de 5 min, turno a favor y en contra, turno de portavoces de 10 min).</li><li><strong>Traslado (8 días)</strong> — el Presidente da traslado del acuerdo al Tribunal Supremo.</li><li><strong>Suspensión temporal</strong> — concedido el suplicatorio y firme el auto de procesamiento, la Cámara puede acordar por mayoría absoluta la suspensión temporal (sesión secreta).</li></ul>', 3);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (3, @seccion_id, 'epigrafe', '3.4', 'Adquisición de la condición de parlamentario', '<p><strong>A) En el Congreso de los Diputados (art. 20)</strong></p><p>Para adquirir la condición plena de Diputado se requieren tres requisitos acumulativos:</p><ul class="uji-lista"><li><strong>1. Presentación de credencial (inmediato)</strong> — presentar en la Secretaría General la credencial expedida por el órgano de la Administración electoral.</li><li><strong>2. Declaración de actividades (inmediato)</strong> — cumplimentar su declaración de actividades en los términos previstos en la LOREG.</li><li><strong>3. Juramento o promesa (primera sesión a la que asista)</strong> — prestar, en la primera sesión del Pleno a que asista, la promesa o juramento de acatar la Constitución.</li></ul><p>Efectos: los derechos y prerrogativas son efectivos desde el momento en que el Diputado es proclamado electo. Sin embargo, si transcurren tres sesiones plenarias sin que adquiera la condición plena, no tendrá derechos ni prerrogativas hasta que la adquisición se produzca.</p><p><strong>B) En el Senado (arts. 11, 12 y 4 bis)</strong></p><p><strong>Juramento o promesa (art. 11)</strong></p><ul class="uji-lista"><li>1. Toma de declaración: el Presidente de la Mesa de edad toma la declaración de acatamiento al Presidente de la misma.</li><li>2. Transmisión: el Presidente la toma a todos los Senadores, empezando por los Vicepresidentes y Secretarios, y continuando por orden alfabético.</li><li>3. Fórmula: "¿Juráis o prometéis acatar la Constitución?" Respuesta: "Sí, juro" o "Sí, prometo".</li></ul><p><strong>Perfección de la condición (art. 12)</strong></p><ul class="uji-lista"><li><strong>a) Presentación de credencial (30 días desde su expedición)</strong> — presentar la credencial expedida por la Junta Electoral Provincial, Central o Asamblea de la CCAA. La Cámara puede ampliar el plazo por enfermedad o imposibilidad física.</li><li><strong>b) Declaraciones obligatorias (junto con la credencial)</strong> — formular las declaraciones de actividades, bienes patrimoniales y rentas, y de intereses económicos (art. 26).</li><li><strong>c) Juramento o promesa (3 meses desde presentación de credencial)</strong> — prestar juramento o promesa (presencial o mediante documento fehaciente).</li></ul><p>Efectos hasta la perfección de la condición (art. 12.2): no devengan derechos económicos ni pueden participar en el ejercicio de las funciones constitucionales de la Cámara.</p>', 4);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (3, @seccion_id, 'epigrafe', '3.5', 'Suspensión de la condición de parlamentario', '<p><strong>A) En el Congreso (art. 21)</strong></p><ul class="uji-lista"><li>1. Disciplina parlamentaria: por aplicación de las normas de disciplina parlamentaria (arts. 99-107).</li><li>2. Prisión preventiva: cuando, concedida la autorización (suplicatorio) y firme el auto de procesamiento, se halle en situación de prisión preventiva y mientras dure ésta.</li><li>3. Sentencia firme: cuando una sentencia firme condenatoria lo comporte o su cumplimiento implique imposibilidad de ejercer la función parlamentaria.</li></ul><p>La suspensión afecta a derechos, prerrogativas y deberes parlamentarios.</p><p><strong>B) En el Senado (art. 18.2)</strong></p><ul class="uji-lista"><li>a) Disciplina parlamentaria: por aplicación de las normas de disciplina parlamentaria.</li><li>b) Prisión provisional: cuando el Senador se halle en situación de prisión provisional, consecuencia de un auto de procesamiento o acto procesal análogo.</li><li>c) Sentencia firme: cuando una sentencia firme condenatoria lo comporte o su cumplimiento implique imposibilidad temporal de ejercer la función parlamentaria.</li></ul>', 5);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (3, @seccion_id, 'epigrafe', '3.6', 'Pérdida de la condición de parlamentario', '<p><strong>A) En el Congreso (art. 22)</strong></p><ul class="uji-lista"><li>1. Anulación judicial: por decisión judicial firme que anule la elección o la proclamación del Diputado.</li><li>2. Fallecimiento o incapacitación: por fallecimiento o incapacitación declarada por decisión judicial firme.</li><li>3. Extinción del mandato: al expirar el plazo (4 años) o disolverse la Cámara (los miembros de la Diputación Permanente continúan en funciones hasta la constitución de la nueva Cámara).</li><li>4. Renuncia: por renuncia del Diputado, presentada ante la Mesa del Congreso.</li></ul><p><strong>B) En el Senado (art. 18)</strong></p><ul class="uji-lista"><li>a) Anulación judicial: anulación de la elección o de la proclamación mediante sentencia judicial firme.</li><li>b) Condena penal: condena a pena de inhabilitación absoluta o especial para cargo público.</li><li>c) Fallecimiento o incapacitación: fallecimiento o, cuando así proceda por resolución judicial, en casos de medidas de apoyo para el ejercicio de su capacidad jurídica.</li><li>d) Pérdida de requisitos: pérdida de los requisitos generales de elegibilidad.</li><li>e) Extinción del mandato: al concluir la legislatura o ser disuelta la Cámara (con prórroga para la Diputación Permanente).</li><li>f) Designación por CCAA: cuando así proceda y se comunique por las Asambleas legislativas de las CCAA.</li><li>g) Renuncia: renuncia efectuada ante la Mesa de la Cámara.</li><li>h) Incompatibilidad: incompatibilidad declarada conforme al art. 17 del Reglamento del Senado.</li></ul>', 6);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (3, @seccion_id, 'epigrafe', '3.7', 'Particularidades del Senado', '<p><strong>A) Declaraciones obligatorias (art. 26)</strong></p><p>Los Senadores deben formular tres declaraciones:</p><ul class="uji-lista"><li><strong>a) Declaración de actividades</strong> — actividades profesionales, mercantiles, laborales, etc.</li><li><strong>b) Declaración de bienes patrimoniales y rentas</strong> — bienes, rentas y patrimonio.</li><li><strong>c) Declaración de intereses económicos</strong> — intereses económicos y participaciones.</li></ul><p><strong>Plazos</strong></p><ul class="uji-lista"><li>Al iniciar el mandato (junto con la credencial).</li><li>En los 30 días naturales siguientes a la pérdida de la condición.</li><li>En los 30 días siguientes a la modificación de las circunstancias inicialmente declaradas.</li></ul><p>Publicidad: las declaraciones se publican en la página web del Senado.</p><p><strong>B) Uso de lenguas oficiales (art. 11 bis)</strong></p><ul class="uji-lista"><li>El Presidente del Senado, en su primera intervención ante el Pleno, puede utilizar el castellano y las demás lenguas oficiales.</li><li>El contenido debe ser idéntico en las diferentes lenguas.</li></ul><p><strong>C) Nueva elección de la Mesa (art. 13)</strong></p><ul class="uji-lista"><li>Si, tras la constitución definitiva del Senado, se incorporan nuevos Senadores y el número de miembros aumenta en más de un 15%, puede procederse a la elección de una nueva Mesa.</li><li>Iniciativa: un Grupo Parlamentario o 25 Senadores.</li></ul><p><strong>D) Comunicación oficial de la constitución (art. 14)</strong></p><p>El Presidente del Senado comunica la constitución definitiva a:</p><ul class="uji-lista"><li>El Rey.</li><li>El Congreso de los Diputados.</li><li>El Gobierno.</li><li>Las Asambleas legislativas (u órganos colegiados superiores) de las Comunidades Autónomas.</li></ul>', 7);

